package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;

/** Actual archived completion, explicit fictional eligibility/source ports for pure mapping only. */
class NewsSourceReportCandidatesTest {
    SourceValueReportCompletionTest f;SourceValueReportCompletionService.Completed done;
    GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreTest();}
    @BeforeEach void setup(){f=new SourceValueReportCompletionTest(){@Override GenerationJdbcStoreTest fixture(){return NewsSourceReportCandidatesTest.this.fixture();}};f.setup();finish();}
    void finish(){f.f.pure=new SourceValueStageResultTest(){@Override tools.jackson.databind.node.ObjectNode payload(SourcePartitionPlanner.Chunk chunk){var payload=super.payload(chunk);var selected=(tools.jackson.databind.node.ArrayNode)payload.get("selected_item_ids");int n=0;for(var row:payload.get("items")){boolean high=n++<5;((tools.jackson.databind.node.ObjectNode)row).put("high_value",high);if(high)selected.add(row.get("item_id").asText());}return payload;}};f.complete();f.original.service.capture(f.f.ref);done=f.find(f.f.clock.instant());}
    Map<String,NewsSourceReportCandidates.Eligibility> eligibility(){var map=new LinkedHashMap<String,NewsSourceReportCandidates.Eligibility>();done.stage().members().forEach(m->map.put(m.itemId(),new NewsSourceReportCandidates.Eligibility(true,false)));return map;}
    NewsSourceReportCandidates.Value value(){return NewsSourceReportCandidates.create(done,done.availableAt(),eligibility());}
    GenerationFlowService.Prepare command(){return new GenerationFlowService.Prepare("fictional-report:daily:"+done.plan().scope().businessDate(),1,GenerationFlowService.Stage.DAILY_REPORT,done.plan().scope().businessDate(),null,List.of(),List.of(),List.of(),false,"a".repeat(64));}
    ReportInputSnapshotService.FrozenInput freeze(NewsSourceReportCandidates.Value value){return new ReportInputSnapshotService((c,t)->new ReportInputSnapshotService.SourceProof(t,c.businessDate(),c.businessDate().plusDays(1),true,value.candidates(),value.missing(),List.of(),value.dependencies().stream().map(GenerationFlowService.Dependency::id).toList())).freeze(command(),done.availableAt());}
    @Test void SourceSummaryAndOnlyOriginalSelectedHighValuesRetainFullRawBodiesAndExplicitMetadata(){
        var value=value();assertEquals(1+done.finalResult().result().selected().size(),value.candidates().size());var summary=value.candidates().getFirst();assertEquals(ReportInputSnapshotService.Group.SOURCE_SUMMARIES,summary.group());assertEquals(done.finalResult().result().json(),summary.evidence().bodyJson());assertEquals(done.finalResult().result().summary(),summary.metadata().summary());assertNull(summary.metadata().title());assertNull(summary.metadata().occurrenceCount());
        for(var candidate:value.candidates().subList(1,value.candidates().size())){assertEquals(ReportInputSnapshotService.Group.HIGH_VALUE_ITEMS,candidate.group());assertTrue(candidate.highValue());String id=candidate.metadata().resourceRef().id();var leaf=value.leaves().stream().filter(l->l.itemId().equals(id)).findFirst().orElseThrow();var chunk=done.plan().chunks().stream().filter(c->c.rootId().equals(leaf.fragmentRoot())).findFirst().orElseThrow();var original=CanonicalJson.parse(chunk.snapshotJson()).get("members");var body=new ArrayList<tools.jackson.databind.JsonNode>();original.forEach(n->{if(id.equals(n.get("id").asText()))body.add(n.get("body"));});assertEquals(1,body.size());assertEquals(body.getFirst(),CanonicalJson.parse(candidate.evidence().bodyJson()));assertEquals(leaf.originalBodyHash(),candidate.evidence().bodyHash());assertEquals(done.availableAt(),candidate.evidence().completedAt());}
        assertEquals(done.stage().members().size(),value.leaves().size());assertEquals(done.stage().fragments().size(),value.dependencies().size());var frozen=freeze(value);assertEquals(value.candidates().size(),CanonicalJson.parse(frozen.snapshotJson()).get("members").size());assertTrue(frozen.hasContent());assertEquals("partial",frozen.coverageState());assertTrue(value.missing().stream().anyMatch(m->"dedup_needs_review".equals(m.reason())));assertThrows(UnsupportedOperationException.class,()->value.candidates().clear());assertThrows(UnsupportedOperationException.class,()->value.leaves().clear());
    }
    @Test void AnyInvalidLeafExcludesItsSummaryButValidSelectedRawEvidenceCanRemain(){
        var map=eligibility();var selectedIds=done.finalResult().result().selected().stream().map(SourceValueFinalResult.Selected::itemId).collect(java.util.stream.Collectors.toSet());String first=done.stage().members().stream().map(m->m.itemId()).filter(id->!selectedIds.contains(id)).findFirst().orElseThrow();map.put(first,new NewsSourceReportCandidates.Eligibility(false,false));var value=NewsSourceReportCandidates.create(done,done.availableAt(),map);assertFalse(value.candidates().getFirst().evidence().effectiveValid());var frozen=freeze(value);assertEquals("partial",frozen.coverageState());assertFalse(CanonicalJson.parse(frozen.snapshotJson()).get("members").valueStream().anyMatch(n->"source_summary".equals(n.get("kind").asText())));assertTrue(frozen.hasContent());assertEquals(selectedIds.size(),CanonicalJson.parse(frozen.snapshotJson()).get("members").size());
    }
    @Test void BlockedLeavesExcludeSummaryAndOnlyTheirOwnSelectedRawBodies(){
        var map=eligibility();String selected=done.finalResult().result().selected().getFirst().itemId();map.put(selected,new NewsSourceReportCandidates.Eligibility(true,true));var value=NewsSourceReportCandidates.create(done,done.availableAt(),map);assertTrue(value.candidates().getFirst().evidence().blocked());assertTrue(value.candidates().stream().filter(c->c.group()==ReportInputSnapshotService.Group.HIGH_VALUE_ITEMS&&selected.equals(c.metadata().resourceRef().id())).findFirst().orElseThrow().evidence().blocked());var frozen=freeze(value);assertFalse(CanonicalJson.parse(frozen.snapshotJson()).get("members").valueStream().anyMatch(n->n.get("body_hash").asText().equals(value.candidates().stream().filter(c->selected.equals(c.metadata().resourceRef().id())).findFirst().orElseThrow().evidence().bodyHash())));
    }
    @Test void ExactAllLeafEligibilityIsMandatoryAndNeverAssumesUnknownIsValid(){
        var missing=eligibility();missing.remove(done.stage().members().getFirst().itemId());assertThrows(RuntimeException.class,()->NewsSourceReportCandidates.create(done,done.availableAt(),missing));var extra=eligibility();extra.put("fictional-foreign-item",new NewsSourceReportCandidates.Eligibility(true,false));assertThrows(RuntimeException.class,()->NewsSourceReportCandidates.create(done,done.availableAt(),extra));assertThrows(RuntimeException.class,()->NewsSourceReportCandidates.create(done,done.availableAt(),null));
    }
    @Test void FutureObservationOrNonMicroCutoffCannotBeConvertedToDailyEvidence(){
        assertThrows(RuntimeException.class,()->NewsSourceReportCandidates.create(done,done.availableAt().minusNanos(1000),eligibility()));assertThrows(RuntimeException.class,()->NewsSourceReportCandidates.create(done,done.availableAt().plusNanos(1),eligibility()));var forged=new SourceValueReportCompletionService.Completed(done.plan(),done.stage(),done.finalResult(),done.finalResult().minimumObservationTime().minusNanos(1000));assertThrows(RuntimeException.class,()->NewsSourceReportCandidates.create(forged,done.availableAt(),eligibility()));
    }
    @Test void ZeroNativeInputDoesNotTurnItsProgrammaticSummaryIntoNewsContent(){
        f.f.install(0);f.original.x.install();f.original.install();f.install();finish();var value=value();assertTrue(value.candidates().isEmpty());assertTrue(value.leaves().isEmpty());assertTrue(value.dependencies().isEmpty());assertFalse(freeze(value).hasContent());assertEquals("no_input",freeze(value).coverageState());
    }
}
